// Title: Validate slicer border thickness and color preservation during Excel to PDF conversion using Aspose.Cells for .NET
// Common Searches: how to verify slicer border color after exporting Excel to PDF with Aspose.Cells in C# | check if slicer formatting is retained in PDF generated by Aspose.Cells .NET | Aspose.Cells PDF conversion slicer border thickness validation C# example | C# code to confirm slicer appearance after saving workbook as PDF | does Aspose.Cells keep slicer border style when converting Excel to PDF
// Tags: Aspose.Cells slicer border validation | Excel to PDF slicer style preservation | C# PDF conversion slicer formatting check | Aspose.Cells PDF export slicer appearance | slicer border thickness retention in PDF

using System;
using System.IO;
using Aspose.Cells;

// The example loads an Excel workbook that may contain slicers, notes that the current Aspose.Cells API does not expose slicer border properties, converts the workbook to PDF, and confirms the PDF file was created, providing robust error handling for file access and conversion steps.
class SlicerPdfValidation
{
    static void Main()
    {
        try
        {
            const string excelPath = "InputWithSlicer.xlsx";
            const string pdfPath = "Converted.pdf";

            // Verify that the input Excel file exists
            if (!File.Exists(excelPath))
            {
                Console.WriteLine($"Error: The file \"{excelPath}\" was not found.");
                return;
            }

            Workbook workbook;
            try
            {
                // Load the workbook (may contain slicers)
                workbook = new Workbook(excelPath);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to load workbook: {ex.Message}");
                return;
            }

            // NOTE: Access to slicer border properties is not available in the current Aspose.Cells version.
            // The code focuses on converting the workbook to PDF safely.

            try
            {
                // Convert the workbook to PDF
                workbook.Save(pdfPath, SaveFormat.Pdf);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"PDF conversion failed: {ex.Message}");
                return;
            }

            // Verify that the PDF was created
            if (File.Exists(pdfPath))
            {
                Console.WriteLine($"Workbook successfully converted to PDF: \"{pdfPath}\"");
            }
            else
            {
                Console.WriteLine("Error: PDF conversion failed; the output file was not created.");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An unexpected error occurred: {ex.Message}");
        }
    }
}
